/** The art of a look (the classic art when a look has none for that hero). */
export const skinArt = (heroIndex: number, skin: SkinId): SkinArt => {
  const generated = skin === 'classic' ? undefined : GENERATED[skin]?.[heroIndex];
  if (generated) return generated;
  const c = characters[heroIndex] ?? characters[0];
  return {
    playerImage: c.playerImage,
    attackImage: c.attackImage,
    scoreImage: c.scoreImage,
    winImage: c.winImage,
    loseImage: c.loseImage,
    frontImage: c.frontImage,
    backImage: c.backImage,
    walkImages: c.walkImages,
  };
};

/** Whether a look has its own art for a hero (an outfit not painted yet has none). */
export const hasSkinArt = (heroIndex: number, skin: SkinId): boolean => skin === 'classic' || !!GENERATED[skin]?.[heroIndex];
